with base(contract)as(select jsonb_build_object(
 'tables',(select jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl)order by c.relname)from pg_class c where c.relnamespace in('public'::regnamespace,'family_auth'::regnamespace) and c.relname in('packing_bags','packing_bag_members','packing_items','packing_category_assignees','packing_categories','packing_category_assignments','packing_command_cancellations','packing_command_receipts','packing_category_batches','packing_category_batch_items','packing_item_recipients','packing_item_contributors')),
 'columns',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid))order by c.relname,a.attnum)from pg_class c join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where c.relnamespace in('public'::regnamespace,'family_auth'::regnamespace) and c.relname in('packing_bags','packing_bag_members','packing_items','packing_category_assignees','packing_categories','packing_category_assignments','packing_command_cancellations','packing_command_receipts','packing_category_batches','packing_category_batch_items','packing_item_recipients','packing_item_contributors')),
 'constraints',(select jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(oid),'validated',convalidated)order by conrelid::regclass::text,conname)from pg_constraint where conrelid in('public.packing_bags'::regclass,'public.packing_bag_members'::regclass,'public.packing_items'::regclass,'public.packing_category_assignees'::regclass,'public.packing_categories'::regclass,'public.packing_category_assignments'::regclass,'family_auth.packing_command_cancellations'::regclass,'family_auth.packing_command_receipts'::regclass,'family_auth.packing_category_batches'::regclass,'family_auth.packing_category_batch_items'::regclass,'public.packing_item_recipients'::regclass,'public.packing_item_contributors'::regclass)),
 'indexes',(select jsonb_agg(jsonb_build_object('table',tablename,'name',indexname,'definition',indexdef)order by tablename,indexname)from pg_indexes where schemaname in('public','family_auth')and tablename in('packing_bags','packing_bag_members','packing_items','packing_category_assignees','packing_categories','packing_category_assignments','packing_command_cancellations','packing_command_receipts','packing_category_batches','packing_category_batch_items','packing_item_recipients','packing_item_contributors')),
 'policies',(select jsonb_agg(to_jsonb(p)order by tablename,policyname)from pg_policies p where schemaname in('public','family_auth')and tablename in('packing_bags','packing_bag_members','packing_items','packing_category_assignees','packing_categories','packing_category_assignments','packing_command_cancellations','packing_command_receipts','packing_category_batches','packing_category_batch_items','packing_item_recipients','packing_item_contributors')),
 'triggers',(select jsonb_agg(jsonb_build_object('table',tgrelid::regclass::text,'name',tgname,'enabled',tgenabled,'definition',pg_get_triggerdef(oid))order by tgrelid::regclass::text,tgname)from pg_trigger where not tgisinternal and tgrelid in('public.packing_bags'::regclass,'public.packing_bag_members'::regclass,'public.packing_items'::regclass,'public.packing_category_assignees'::regclass,'public.packing_categories'::regclass,'public.packing_category_assignments'::regclass,'family_auth.packing_command_cancellations'::regclass,'family_auth.packing_command_receipts'::regclass,'family_auth.packing_category_batches'::regclass,'family_auth.packing_category_batch_items'::regclass,'public.packing_item_recipients'::regclass,'public.packing_item_contributors'::regclass)),
 'function_contract',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'acl',p.proacl,'definer',p.prosecdef,'volatility',p.provolatile,'config',p.proconfig)order by p.oid::regprocedure::text)from pg_proc p where p.oid::regprocedure::text like '%packing%'))::text)select(contract::jsonb||jsonb_build_object('identity_triggers',(select jsonb_agg(jsonb_build_object('table',tgrelid::regclass::text,'name',tgname,'enabled',tgenabled,'definition',pg_get_triggerdef(oid))order by tgrelid::regclass::text,tgname)from pg_trigger where not tgisinternal and tgrelid in('public.people'::regclass,'public.trips'::regclass))))::text from base;
